css.value:
* { 
    color: --now-color_text--primary;

/* Display type/header primary */
font-family: var(--Typography-Font---now-heading--font-family, Cabin);
font-size: var(--Typography-Size-Display-header-primary, 24px);
font-style: normal;
font-weight: 700;
line-height: normal;
}

script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var selectedItem = event.payload.item.id;
    var trendFreq = (selectedItem == "monthly") ? "MONTH" : "WEEK";

    return {
        propName: "trendFrequency",
        value: trendFreq
    };
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "driverTablePaginationCurrentPage",
		value: Number(event.payload.value)
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		propName: "driverTablePaginationRowsPerPage",
		value: Number(event.payload.value)
	};
}
